     for (const encontro of encontros) {
       const inicio = new Date(encontro.inicio);
       const fim = new Date(encontro.fim);
       const duracao = fim - inicio;
       if (duracao < DURACAO_MIN_MS || duracao > DURACAO_MAX_MS) {
