       return res.status(422).json({
         erro: 'CAMPO_NAO_EDITAVEL',
         mensagem: 'Apenas titulo e vagas podem ser alterados.'
       });
     }

     if (titulo !== undefined) {
       atividade.titulo = titulo;
     }
     if (vagas !== undefined) {
+      if (vagas < 1) {
+        return res.status(422).json({
+          erro: 'DADOS_INVALIDOS',
