+          erro: 'VAGAS_ACIMA_DA_CAPACIDADE',
+          mensagem: 'vagas não pode ultrapassar a capacidade da sala.'
+        });
+      }
       atividade.vagas = vagas;
     }

     res.status(200).json(serializarAtividade(atividade, agora()));
   });

